D={
10159:("Who e what","**Who** pergunta por pessoa; **what** pergunta por coisa. *Who is at the door? What is that?*",[("{{Who}} is at the door?","Quem está na porta?"),("It's a stranger.","É um desconhecido."),("{{What}} is in the package?","O que há no pacote?"),("I don't know.","Não sei.")],"Para perguntar por uma pessoa, use…",["what","who","where"],1,"Who = quem."),
70037:("Who's calling?","**Who's** = who is. *Who's calling? Who's there?* Na fala ao telefone, é uma pergunta muito comum.",[("{{Who's}} calling?","Quem está ligando?"),("It's a visitor.","É uma visita."),("{{Who's}} there?","Quem está aí?"),("Leave a message, please.","Deixe um recado, por favor.")],"Who's significa…",["who is","who has","whose"],0,"Who's = who is."),
30019:("Who is it for?","**Who is it for?** = para quem é? **Who is it from?** = de quem é (remetente)? A preposição fica no fim.",[("{{Who is it for}}?","Para quem é?"),("It's {{for}} my sister.","É para minha irmã."),("{{Who is it from}}?","De quem é?"),("It's {{from}} the mailman.","É do carteiro.")],"Como perguntar de quem veio o pacote?",["Who is it from?","Who it is of?","From who is?"],0,"Who is it from?"),
70038:("For e from","**For** = para (destinatário). **From** = de (origem). *A card for you. A card from me.*",[("This card is {{for}} you.","Este cartão é para você."),("It's {{from}} the guests.","É dos convidados."),("There are candles.","Há velas."),("Happy birthday!","Feliz aniversário!")],"“Este presente é para você”:",["This gift is from you.","This gift is for you.","This gift for to you."],1,"for = para."),
910009:("Take a shower","Com **take**: *take a shower, take a bus, take a bath, take a nap.* Em português usamos outro verbo, em inglês é **take**.",[("I {{take a shower}} every morning.","Tomo banho toda manhã."),("We {{take the tram}}.","Pegamos o bonde."),("He {{takes a nap}}.","Ele tira uma soneca."),("Put on your bathrobe.","Vista seu roupão.")],"Como dizer “tomar banho”?",["take a shower","do a shower","make a shower"],0,"take a shower."),
10160:("Mine, yours, his, hers","**Mine, yours, his, hers** substituem o nome: *It's mine.* **My** vem antes do nome; **mine** fica sozinho.",[("It's {{my}} ring.","É meu anel."),("It's {{mine}}.","É meu."),("That locker is {{hers}}.","Aquele armário é dela."),("This tag is {{his}}.","Esta etiqueta é dele.")],"Qual forma fica sozinha?",["my","mine","me"],1,"Mine não precisa de nome."),
70039:("It's yours, it's hers","**Yours** = seu(s); **hers** = dela; **his** = dele. *The remote is yours. The tablet is hers.*",[("The remote is {{yours}}.","O controle é seu."),("The headphones are {{hers}}.","Os fones são dela."),("The helmet is {{his}}.","O capacete é dele."),("The sunglasses are {{mine}}.","Os óculos são meus.")],"“Os óculos são dela”:",["The sunglasses are hers.","The sunglasses are her.","The sunglasses is hers."],0,"hers sozinho."),
30020:("Whose…?","**Whose** pergunta o dono: **Whose coat is that?** Resposta: **It's mine / his / hers.** Não confunda com *who's*.",[("{{Whose}} coat is that?","De quem é aquele casaco?"),("It's {{mine}}.","É meu."),("{{Whose}} boots are these?","De quem são estas botas?"),("They're {{hers}}.","São dela.")],"“De quem é este chapéu?”",["Who's hat is this?","Whose hat is this?","Of who hat?"],1,"Whose = de quem."),
70040:("Leave your…","**Leave your umbrella** = deixe seu guarda-chuva. Possessivos antes do nome: *my, your, his, her, our, their*.",[("{{Leave your}} umbrella here.","Deixe seu guarda-chuva aqui."),("{{My}} raincoat is wet.","Minha capa de chuva está molhada."),("{{Her}} scarf is red.","O cachecol dela é vermelho."),("The wind is strong.","O vento está forte.")],"Complete: “___ scarf is warm.” (dele)",["His","Him","Hers"],0,"his + nome."),
10161:("Revisão: be","Revisão rápida de **be**: afirmativa **I'm**, negativa **I'm not**, pergunta **Are you…?**, resposta curta **Yes, I am.**",[("I'm ready for the {{quiz}}.","Estou pronto para o teste."),("{{Are you}} ready?","Você está pronto?"),("Yes, {{I am}}.","Sim."),("No, {{I'm not}}.","Não.")],"Qual é uma pergunta com be?",["You are ready?","Are you ready?","Do you ready?"],1,"Are you…? — verbo antes."),
70041:("Parabenizar","Para elogiar: **You did great!** / **Well done!** / **Great job!** Respostas: **Thanks!** / **Thank you!**",[("{{You did great}}!","Você foi muito bem!"),("{{Well done}}!","Muito bem!"),("{{Great job}}!","Ótimo trabalho!"),("Thank you!","Obrigado!")],"Uma boa resposta a “Great job!”",["Thank you!","Sorry.","Please."],0,"Thank you!"),
30021:("Sorry, I'm late","Para pedir desculpas: **Sorry, I'm late.** / **I'm sorry.** / **My mistake.** Resposta: **It's OK.** / **No problem.**",[("{{Sorry, I'm late}}.","Desculpe, estou atrasado."),("{{I'm sorry}} about the mistake.","Sinto muito pelo erro."),("{{It's OK}}.","Tudo bem."),("{{No problem}}.","Sem problema.")],"O que dizer para aceitar desculpas?",["It's OK.","Sorry.","Please."],0,"It's OK."),
70042:("Don't be…","Para tranquilizar: **Don't be nervous.** O imperativo negativo é **Don't + verbo**. *Don't worry. Don't be afraid.*",[("{{Don't be}} nervous.","Não fique nervoso."),("{{Don't worry}}.","Não se preocupe."),("You are brave!","Você é corajoso!"),("The audience is kind.","A plateia é gentil.")],"Como se diz “Não se preocupe”?",["Don't worry.","No worry you.","Not worry."],0,"Don't + verbo."),
910010:("Make tea","Com **make**: *make tea, make a cake, make noise, make a mistake.* Com **do**: tarefas. *do homework.*",[("I {{make tea}}.","Eu faço chá."),("She {{makes a cake}}.","Ela faz um bolo."),("Don't {{make noise}}!","Não faça barulho!"),("Add some stew.","Acrescente ensopado.")],"“Fazer um bolo”:",["do a cake","make a cake","take a cake"],1,"make a cake."),
10162:("A e an","**A** antes de som de consoante: *a dog*. **An** antes de som de vogal: *an elephant, an egg, an onion.* Vale o **som**, não a letra.",[("{{An}} elephant is big.","Um elefante é grande."),("I have {{an}} egg.","Tenho um ovo."),("It's {{a}} lion.","É um leão."),("{{An}} onion, please.","Uma cebola, por favor.")],"Qual está certa?",["a egg","an egg","an dog"],1,"Egg: som de vogal → an."),
70043:("Pass the…","Para pedir à mesa: **Pass the salt, please.** Verbo no começo + **please**. Para agradecer: **Thank you.**",[("{{Pass}} the salt, please.","Passe o sal, por favor."),("{{Pass}} the pepper.","Passe a pimenta."),("A fork and a knife.","Um garfo e uma faca."),("Here's your plate.","Aqui está o seu prato.")],"“Passe a colher, por favor”:",["Pass the spoon, please.","The spoon pass.","You pass spoon."],0,"Pass + objeto + please."),
30022:("Do you have…?","Para perguntar se alguém tem algo: **Do you have a bucket?** Resposta: **Yes, I do. / No, I don't.**",[("{{Do you have}} a bucket?","Você tem um balde?"),("Yes, {{I do}}.","Sim, tenho."),("{{Do you have}} any stones?","Você tem pedras?"),("No, {{I don't}}.","Não, não tenho.")],"Resposta curta de sim a Do you have a fish?",["Yes, I do.","Yes, I have.","Yes, I am."],0,"do."),
70044:("Do you have…?","Também serve para roupas: **Do you have a size small?** *Do you have jeans?* Para falar de quem tem: **I have / she has.**",[("{{Do you have}} a jacket?","Você tem uma jaqueta?"),("Yes, {{I have}} a jacket.","Sim, tenho uma jaqueta."),("She {{has}} a dress.","Ela tem um vestido."),("Where is my belt?","Onde está meu cinto?")],"She ___ shorts.",["have","has","haves"],1,"Com she: has."),
10163:("Profissões","Para dizer a profissão: **He is a farmer.** *She is a pilot.* Use **a/an** antes da profissão. **An** antes de vogal: *an artist*.",[("He {{is a}} farmer.","Ele é agricultor."),("She {{is a}} singer.","Ela é cantora."),("He {{is an}} artist.","Ele é artista."),("They are bakers.","Eles são padeiros.")],"Qual está certa?",["She is pilot.","She is a pilot.","She a pilot."],1,"is a + profissão."),
70045:("Plural -s","Plural simples: **+s**. *library → libraries* (-y vira -ies). *church → churches* (-ch vira -es). *cinema → cinemas*.",[("One {{cinema}}, two {{cinemas}}.","Um cinema, dois cinemas."),("One {{church}}, two {{churches}}.","Uma igreja, duas igrejas."),("One {{library}}, two {{libraries}}.","Uma biblioteca, duas bibliotecas."),("The castle is old.","O castelo é antigo.")],"Plural de church:",["churchs","churches","churchies"],1,"Termina em -ch: -es."),
30023:("Plural -ies / -es","**Consoante + y** → **-ies** (*baby → babies*). **-s, -x, -ch, -sh** → **-es** (*box → boxes*).",[("One {{baby}}, two {{babies}}.","Um bebê, dois bebês."),("One {{box}}, two {{boxes}}.","Uma caixa, duas caixas."),("{{Is there}} a slide?","Tem escorregador?"),("{{Are there}} swings?","Tem balanços?")],"Plural de box:",["boxs","boxes","boxies"],1,"-x → -es."),
70046:("Plural -ies / -es","*Berry → berries*, *potato → potatoes*. Cuidado: *bean → beans*, *nut → nuts* (regular com **-s**).",[("One {{berry}}, two {{berries}}.","Uma fruta, duas frutas."),("One {{potato}}, two {{potatoes}}.","Uma batata, duas batatas."),("{{Beans}} and {{nuts}}.","Feijões e nozes."),("Add honey and jam.","Acrescente mel e geleia.")],"Plural de bean:",["beans","beanes","beanies"],0,"Regular: +s."),
910011:("Do homework","Com **do**: tarefas e atividades: *do homework, do the dishes, do the laundry, do a favor.* **Make** é para criar algo.",[("I {{do my homework}}.","Faço minha lição."),("She {{does the dishes}}.","Ela lava a louça."),("We {{do the laundry}}.","Lavamos a roupa."),("Can you {{do me a favor}}?","Pode me fazer um favor?")],"“Lavar a louça”:",["do the dishes","make the dishes","take the dishes"],0,"do the dishes."),
10164:("Plurais irregulares","Alguns plurais **mudam por inteiro**: *man → men, woman → women, child → children, foot → feet, tooth → teeth.*",[("One {{man}}, two {{men}}.","Um homem, dois homens."),("One {{child}}, two {{children}}.","Uma criança, duas crianças."),("My {{feet}} are cold.","Meus pés estão frios."),("This mountain is big.","Esta montanha é grande.")],"Plural de child:",["childs","children","childes"],1,"Irregular: children."),
70047:("Plurais irregulares","*Man, woman, person* têm plural especial: **men, women, people**. *The bride and groom. The people are happy.*",[("The {{men}} wear suits.","Os homens usam terno."),("The {{women}} dance.","As mulheres dançam."),("The {{people}} are happy.","As pessoas estão felizes."),("A photo of the band.","Uma foto da banda.")],"Plural de woman:",["womans","women","womenes"],1,"Irregular: women."),
30024:("Plural que não muda","Alguns plurais **não mudam**: *sheep, fish, deer.* *One sheep, two sheep.* Só o verbo marca o plural.",[("One {{sheep}}, two {{sheep}}.","Uma ovelha, duas ovelhas."),("One {{fish}}, five {{fish}}.","Um peixe, cinco peixes."),("The ducks are on the farm.","Os patos estão na fazenda."),("A rabbit, a horse, a cow.","Um coelho, um cavalo, uma vaca.")],"Plural de sheep:",["sheep","sheeps","sheepes"],0,"Não muda."),
70048:("Plural que não muda","Cuidado: *wing → wings, feather → feathers.* Mas *sheep* e *fish* não mudam. **Leash, cage, collar** são regulares.",[("Two {{wings}}.","Duas asas."),("Many {{feathers}}.","Muitas penas."),("Two {{sheep}}.","Duas ovelhas."),("The {{leash}} and the {{collar}}.","A guia e a coleira.")],"Qual plural não muda?",["wings","sheep","cages"],1,"Sheep fica igual."),
10165:("On, in, under","**On** = sobre, **in** = dentro, **under** = embaixo. *The ball is on the table. The shoes are under the bed.*",[("The ball is {{on}} the field.","A bola está no campo."),("The player is {{in}} the stadium.","O jogador está no estádio."),("The shoes are {{under}} the bench.","Os sapatos estão embaixo do banco."),("It's a match!","É uma partida!")],"Complete: “The cat is ___ the box.” (dentro)",["on","in","under"],1,"In = dentro."),
70049:("In + estação","Para estações use **in**: *in winter, in summer, in spring, in autumn.* Para fim de semana: **at the weekend**.",[("I like swimming {{in summer}}.","Gosto de nadar no verão."),("It snows {{in winter}}.","Neva no inverno."),("Flowers grow {{in spring}}.","As flores crescem na primavera."),("We rest {{at the weekend}}.","Descansamos no fim de semana.")],"Qual preposição usar com estações?",["on","in","at"],1,"in winter, in summer."),
30025:("Where is / are","Singular: **Where is the guitar?** Plural: **Where are the drums?** Resposta com preposição: *It's on the chair.*",[("{{Where is}} the guitar?","Onde está a guitarra?"),("It's {{on}} the chair.","Está na cadeira."),("{{Where are}} the drums?","Onde estão os tambores?"),("They're {{under}} the stage.","Estão embaixo do palco.")],"Complete: “Where ___ the violins?”",["is","are","do"],1,"Plural: are."),
}
